-- Reference SQL for migration 0011. Conditional legacy-column repair is
-- intentionally implemented by internal/store/sqlstore in Go.
CREATE TABLE IF NOT EXISTS vote_flow_runs (id INT PRIMARY KEY AUTO_INCREMENT, project_id INT NOT NULL, version_no INT NOT NULL DEFAULT 1, status VARCHAR(30) NOT NULL DEFAULT 'active', created_by INT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, archived_at DATETIME NULL, snapshot_json TEXT, UNIQUE KEY uq_vote_flow_run_version (project_id,version_no));
CREATE TABLE IF NOT EXISTS vote_flow_pools (id INT PRIMARY KEY AUTO_INCREMENT, run_id INT NOT NULL, project_id INT NOT NULL, stage_id INT NOT NULL, stage_type VARCHAR(40) NOT NULL, title VARCHAR(160) NOT NULL DEFAULT '', status VARCHAR(30) NOT NULL DEFAULT 'draft', vote_mode VARCHAR(40) NOT NULL DEFAULT 'multi_select', group_count INT NOT NULL DEFAULT 1, max_select INT NOT NULL DEFAULT 1, advance_count INT NOT NULL DEFAULT 0, config_json TEXT, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, opened_at DATETIME NULL, settled_at DATETIME NULL, UNIQUE KEY uq_vote_flow_pool_stage (run_id,stage_id));
CREATE TABLE IF NOT EXISTS vote_flow_pool_entries (id INT PRIMARY KEY AUTO_INCREMENT, run_id INT NOT NULL, pool_id INT NOT NULL, project_id INT NOT NULL, entry_id INT NOT NULL, group_key VARCHAR(80) NOT NULL DEFAULT '', seed_no INT NOT NULL DEFAULT 0, source_pool_id INT NULL, source_rank INT NULL, status VARCHAR(30) NOT NULL DEFAULT 'active', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_vote_flow_pool_entry (pool_id,entry_id));
CREATE TABLE IF NOT EXISTS vote_flow_results (id INT PRIMARY KEY AUTO_INCREMENT, run_id INT NOT NULL, pool_id INT NOT NULL, project_id INT NOT NULL, entry_id INT NOT NULL, rank_no INT NOT NULL DEFAULT 0, votes INT NOT NULL DEFAULT 0, score_total INT NOT NULL DEFAULT 0, rating_count INT NOT NULL DEFAULT 0, score_avg DECIMAL(8,3) NULL, advanced TINYINT NOT NULL DEFAULT 0, snapshot_json TEXT, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_vote_flow_result (pool_id,entry_id));
CREATE TABLE IF NOT EXISTS vote_flow_matches (id INT PRIMARY KEY AUTO_INCREMENT, run_id INT NOT NULL, pool_id INT NOT NULL, project_id INT NOT NULL, stage_id INT NOT NULL, round_no INT NOT NULL DEFAULT 1, match_no INT NOT NULL DEFAULT 1, slot_a_entry_id INT NULL, slot_b_entry_id INT NULL, winner_entry_id INT NULL, status VARCHAR(30) NOT NULL DEFAULT 'pending', next_match_id INT NULL, next_slot VARCHAR(1) NOT NULL DEFAULT '', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS vote_flow_events (id INT PRIMARY KEY AUTO_INCREMENT, run_id INT NULL, pool_id INT NULL, project_id INT NOT NULL, event_type VARCHAR(80) NOT NULL, payload_json TEXT, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
